using System;
using System.Collections.Generic;

namespace DragLab.Runtime
{
    // Shared plain-language help for inspection, shop, tuning and setup comparisons.
    // These describe tendencies, not a promise that changing one number fixes a build.
    internal static class NativeStatHelp
    {
        internal sealed class Directions
        {
            internal readonly string More,Less,HigherDrawback,LowerDrawback;
            internal Directions(string more,string less,string higher,string lower)
            {More=more;Less=less;HigherDrawback=higher;LowerDrawback=lower;}
        }
        static readonly Dictionary<string,Directions> entries=new Dictionary<string,Directions>(StringComparer.Ordinal);
        static void Add(string ids,string more,string less,string higher=null,string lower=null)
        {foreach(string id in ids.Split('|'))entries.Add(id,new Directions(more,less,higher,lower));}
        static NativeStatHelp()
        {
            Add("peakHp|tuningHp","More engine power helps the car keep accelerating as speed rises, if the tires and drivetrain can use it.","Less power generally means slower acceleration at speed, but gives the drivetrain less work to handle.","The extra power can increase fuel use, heat and wheelspin. Check grip and component strength; more power alone does not guarantee a quicker run.","Lower power can cost acceleration and finishing speed.");
            Add("peakTorque|tuningTorque","More twisting force from the engine can give a stronger pull. Gears multiply this force before it reaches the tires.","Less twisting force usually gives a gentler pull and puts less strain on the drivetrain.","The stronger pull can overwhelm the clutch, drivetrain or tires, depending on gearing and grip.","Less engine force can make the car slower to pick up speed.");
            Add("hpRpm|torqueRpm","The strongest part of the engine's pull happens later in the rev range. Gearing and shift timing need to keep the engine near that range.","The strongest pull arrives at lower revs, which can help launch and recovery after a shift.","Reaching the useful power band may require more revs or shorter gearing.","The engine may run past its strongest range earlier; check the whole curve before choosing shift points.");
            Add("cylinders","More cylinders divide combustion into more firing events. Count describes the engine design, not how many cylinders are currently healthy.","Fewer cylinders change the firing rhythm and engine character. Count alone does not tell you power, efficiency or durability.","More cylinders mean more individual components to maintain; power still depends on the rest of the engine.","Fewer cylinders do not automatically mean a weaker engine. Compare power and condition separately.");
            Add("displacement","A larger engine moves more air each cycle and can produce more pulling force. The fitted parts still determine the actual power curve.","A smaller engine moves less air each cycle, so it may need more revs or boost to make similar power.","A larger engine can use more fuel and add weight; check those figures separately.","Matching the same output may require more revs or boost, increasing demands elsewhere.");
            Add("idleRpm","A higher warm-idle target keeps the engine turning faster while waiting. Actual idle can still vary with cold starts, cams and faults.","A lower target keeps waiting revs down, but must still be high enough for the engine to run steadily.","Higher idle can use more fuel and sound busier while waiting.","Too low a target can make a difficult engine stumble or stall.");
            Add("redlineRpm|limiterRpm|rpm","A higher RPM limit leaves more room to rev. Redline, the electronic cut target and individual part strength are different limits.","A lower limit reduces available revs. An electronic cut can stop acceleration earlier, even if the engine could safely rev higher.","Extra revs can exceed another part's safe speed. An electronic limiter cannot stop the wheels forcing the engine too fast after a bad downshift.","A lower limit can shorten each gear's usable speed range or cut off useful power.");
            Add("bore","A wider cylinder needs a correctly sized piston and matching engine hardware. This is a fitment dimension, not a power rating.","A narrower cylinder needs correspondingly sized parts; smaller is not automatically weaker.","Parts sized for a different bore may not fit. Compare the complete engine, not bore alone.","Parts sized for a different bore may not fit. No power change is guaranteed by bore alone.");
            Add("valvesPerCylinder","More valves describe more openings per cylinder for air to enter and exhaust to leave. Cam and head design determine how well they work.","Fewer valves describe a different head design, rather than a condition or power score.","There are more individual valves and springs to service; count alone does not guarantee extra power.","Airflow may be more limited, but the actual head and power curve decide the result.");
            Add("camLift|camlift","The cam opens each valve farther, which can let the engine breathe more freely when the head supports it.","The valve opens less far, reducing the space and spring travel needed.","The springs need enough travel, and the piston needs room below the valve. A bad match can cause contact and damage.","Reduced valve opening can limit breathing and power.");
            Add("camDuration|duration","The valves stay open for more crankshaft rotation. This tends to move the useful pull toward higher revs.","The valves stay open for less rotation, usually favoring lower-rev operation and a steadier idle.","A longer opening can weaken low-rev pull and make idle rougher; match the gearing and springs.","A shorter opening can limit high-rev breathing and peak power.");
            Add("camOverlap|overlap","Intake and exhaust valves are open together for longer. This changes breathing, especially at higher revs.","They spend less time open together, usually giving a calmer idle and cleaner low-rev operation.","Extra overlap can cause rough idle and mixture problems at low revs; it is not a universal power gain.","Less overlap can reduce high-rev breathing with an aggressive engine setup.");
            Add("camSeparation|lsa","The intake and exhaust cam peaks are farther apart. With the same duration this generally reduces the time both valves are open together.","The peaks are closer together. With the same duration this generally increases that shared opening time.","A wider spacing can reduce the high-rev benefit of overlap; check the full cam profile.","A narrower spacing can make idle rougher and low-rev running less clean.");
            Add("compression","The engine squeezes the air and fuel more tightly before burning it. This can improve efficiency and response when fuel and engine design support it.","The air and fuel are squeezed less tightly, giving petrol engines more room for boost before harmful uncontrolled burning, called knocking.","Petrol can burn too early or unevenly under heavy load or boost, causing damaging knock. Diesel uses a different combustion system, so compare compatible engine parts.","Lower compression can weaken response and efficiency; too little is especially unsuitable for compression-ignition diesel engines.");
            Add("valveClearance|relief","More space between valve and piston, or a deeper piston valve recess, gives the valve more room to move.","Less space leaves less room for cam lift and timing changes.","Extra clearance is safety room, not free power. Check compression and the rest of the piston design separately.","Insufficient clearance can make valves strike pistons and damage the engine.");
            Add("springTravel|springlift","The spring allows the valve to move farther before its coils close together. Its safe RPM rating is a separate requirement.","The spring permits less valve movement, so it needs a lower-lift cam.","Extra travel does not guarantee control at high revs; the spring's control rating must also match the cam.","Too little travel for the cam can jam the spring and damage the valve mechanism.");
            Add("camTiming","A more positive setting opens the valves earlier, tending to favor lower-rev pull.","A more negative setting opens them later, tending to favor higher-rev pull.","Moving timing away from its base position reduces the modeled valve clearance; too much advance can also weaken high-rev pull.","Retarding timing can weaken low-rev pull. Moving away from the base position also reduces modeled valve clearance.");
            Add("turboCount","More turbo units change how the engine divides airflow and exhaust flow. Two units are not automatically twice as powerful.","Fewer units simplify the layout; their size and flow still determine boost and response.","Extra units add complexity; compare boost, response and weight rather than assuming extra power.","The remaining turbo layout may support less flow or respond differently.");
            Add("superchargerCount","More engine-driven compressors change the available airflow. The engine spends some of its own power driving them.","Fewer compressors reduce the number of driven units, with flow depending on their size and drive ratio.","More compressor drive can consume engine power and increase charge heat.","The smaller compressor arrangement may provide less airflow.");
            Add("boostBar|boostLimit|boostSetting|boost|boostfloor","More boost pressure or a higher boost target can push more air into the engine. Actual power depends on airflow, fuel delivery and temperature.","Less boost reduces the pressure demand and usually reduces heat and engine stress.","The higher boost demand can increase heat, fuel use and knock or component stress. A hardware ceiling is permission, not actual boost; a spring floor cannot be tuned below its fixed value.","Less boost can reduce power; a lower hardware ceiling limits what a future tune can request.");
            Add("turboSize|turbohardware","A larger turbo can support more airflow, but usually needs more exhaust energy and time to build boost. Size is relative to reference hardware, not a diameter.","A smaller turbo usually responds sooner, but has a lower airflow ceiling.","The larger unit may feel weak before it has built boost and may not help a low-flow engine.","A smaller unit can run out of airflow before the engine reaches its desired power.");
            Add("turboSpool|spoolscale","A larger response time means boost takes longer to catch up when throttle or engine load changes.","A smaller response time means boost responds sooner. Actual response still depends on revs, exhaust energy and load.","Slower boost arrival can weaken launches and recovery after lifting off.","Quicker boost can arrive more abruptly, so check available grip.");
            Add("pulleyRatio|pulley","A larger drive ratio spins the supercharger faster for the same engine revs, potentially increasing boost.","A smaller ratio spins it more slowly and reduces its drive demand.","Faster compressor drive consumes more engine power and produces more heat.","Slower drive can reduce boost and power.");
            Add("intercooler","More cooling of compressed intake air keeps the charge cooler under boost. This is separate from cooling the engine itself.","Less charge cooling leaves hotter air entering the engine under boost.",null,"Hotter intake air can reduce useful power and increase petrol knock risk.");
            Add("turboFlow|blowerFlow","A higher airflow rating gives the compressor more room to feed a demanding engine. The rating is per unit, before size or drive-ratio effects.","A lower rating can become a bottleneck at high engine demand.","Unused flow capacity does not add power by itself; size, response and heat may change with the chosen hardware.","Insufficient flow can limit boost-supported power.");
            Add("turboEfficiency|blowerEfficiency","The compressor turns more of its input energy into useful compression rather than heat and losses.","More energy is lost heating the intake air or driving the compressor.",null,"Lower efficiency can mean hotter intake air and less useful engine output.");
            Add("finalDrive|fixedratio|gearRatio|cvtMinimum|cvtMaximum","A higher ratio gives the wheels more leverage from the engine, but less road speed at the same revs.","A lower ratio gives more road speed per engine revolution, but less leverage for acceleration.","The car reaches its RPM limit sooner and may need more shifts; extra wheel torque can exceed grip.","The engine may struggle to pull the taller gearing, especially at launch.");
            Add("shiftSeconds|shift|selector","A longer handover keeps the transmission changing gears for longer. The selector multiplier changes time, not engine power.","A shorter handover restores the next gear's drive sooner, subject to the installed clutch or converter.","Longer shifts interrupt acceleration for longer.","A faster handover can load the drivetrain more abruptly; it does not remove clutch or tire limits.");
            Add("shiftRetention","More engine torque is kept during the gear handover, before live clutch or converter losses.","Less torque is kept during handover, giving a gentler but more interrupted shift.","Keeping more torque can increase post-shift wheelspin or component load.","Less retained torque can cost acceleration during the shift.");
            Add("clutchCapacity|torque|capacity","The component can transfer or withstand more force. A stronger clutch slips less under the same demand; brakes can stop harder only while tires retain grip.","There is less force headroom before slip, a stopping limit or damage, depending on the component.","Capacity alone creates no engine power or tire grip. A stronger clutch may pass more load to weaker drivetrain parts.","Lower capacity may cause clutch slip, weaker braking or overload of a torque-bearing part.");
            Add("converterStall","A higher stall calibration lets the engine reach higher revs while the car is held still against the torque converter.","A lower calibration couples at lower revs, which can feel gentler but may put the engine below its strongest pull.","Higher stall can create more converter slip and heat while held or launching.","Lower stall can make launch sluggish if the engine needs higher revs to pull well.");
            Add("converterMultiply","More low-speed torque multiplication increases launch force; it fades as the converter's output catches up to engine speed.","Less multiplication gives less launch leverage.","Extra launch force can exceed tire grip or drivetrain strength.","Less launch leverage can slow the start.");
            Add("converterLock","A higher lock-up speed keeps the converter unlocked until later. Live throttle and shift conditions also affect lock-up.","A lower speed allows lock-up earlier, reducing slip when conditions permit.","Later lock-up can mean more heat and power lost through slip.","Earlier lock-up can pull engine revs down sooner, weakening acceleration if the engine is below its useful range.");
            Add("cvtTarget|shiftTarget|shiftLightTarget","A higher working or shift target uses more revs before changing ratio or asking the driver to shift. The light is only an alert.","A lower target shifts or alerts earlier, using the lower part of the engine's pull.","Waiting too long can run past useful power or safe RPM. The light itself adds no protection.","Shifting too early can drop the engine below its useful power or boost range.");
            Add("launchTarget|twoStepTarget","A higher launch target holds more engine speed before launch. The actual cut depends on the installed controller.","A lower launch target starts with less engine speed and stored rotating energy.","Launching at higher revs can create wheelspin, clutch heat and a harsher drivetrain load.","Too few revs can make the engine bog down or build boost slowly.");
            Add("awdFrontBias|awdMinimumFront|awdMaximumFront|frontWeight","More of the configured torque share or static weight is toward the front axle. Torque allocation and weight are different things; live behavior also depends on the AWD hardware.","The balance moves toward the rear axle. Acceleration also moves weight rearward.","More front drive can overwhelm front tires as weight moves backward; extra front weight can leave less static load at the rear.","More rear drive can overwhelm rear tires; less front weight can reduce grip available to a front-driven car.");
            Add("awdSecondary|awdPreload","More secondary-axle involvement makes more drive available at the other axle, within the coupling's capacity.","Less involvement leaves more work to the primary axle.","A stronger coupling can load both branches more; it does not create extra tire grip.","The primary axle may spin before enough help arrives from the other axle.");
            Add("awdResponse","A longer response time brings in the other axle's drive more slowly.","A shorter time lets the coupling respond sooner to changing grip.","The primary axle can keep slipping longer before assistance builds.","A quicker coupling can transfer load more abruptly.");
            Add("awdSlipThreshold","More primary-axle slip is allowed before on-demand AWD brings in the other axle.","The other axle is called in after a smaller amount of slip.","More wheelspin can occur before help arrives.","Earlier engagement may load the secondary branch more often; this does not increase tire grip.");
            Add("centerBias|bias","More torque can be directed to the side with more resistance, within this limited-slip differential's limit.","Less bias gives less help to the side with better grip when the other side slips.","A higher ratio still needs some resistance on the weaker side; it cannot guarantee drive through a disconnected branch.","On uneven grip, the weaker side can limit usable drive more strongly.");
            Add("centerPreload|preload","More baseline coupling force helps share drive even when one side has very little resistance.","Less baseline coupling allows the two sides to act more freely.","Extra coupling can send more load through the linked drivetrain; it cannot repair a broken branch.","A nearly unloaded or disconnected side may leave little useful drive at the other side.");
            Add("brakeG","A higher brake rating can produce stronger stopping force, until the tires' grip becomes the limit.","A lower brake rating means less available stopping force. Brake failure does not stop the engine running.",null,"Stopping distances can grow; tire grip is still a separate limit.");
            Add("wheelRadius|wheelDiameter|gearSpeed|cvtSpeed","A taller tire or higher theoretical redline speed covers more road distance at the same engine revs. Tire radius includes the sidewall, not just the rim.","A shorter tire or lower redline speed gives more engine revs per road speed and can improve leverage at launch.","Taller effective gearing can weaken launch. Larger tires can also add rotating load. A theoretical speed does not guarantee the engine can reach it.","The engine hits its RPM limit at a lower road speed and may need more shifts.");
            Add("wheelWidth","A wider modeled tire can improve available contact grip, with pressure and axle load still important. This number is relative width, not millimeters.","A narrower tire can reduce assembly mass but provides less width-based grip.","Greater width can add tire mass and rotating load; compare the resulting grip and inertia together.","Reduced contact grip may increase wheelspin.");
            Add("tirePressure","More pressure makes the tire firmer. Grip and life depend on staying near the setup's suitable pressure, not simply maximizing it.","Less pressure makes the tire softer; lowering it too far also hurts grip and life.","Too much pressure can reduce modeled grip and speed up tire wear.","Too little pressure can also reduce grip and speed up wear.");
            Add("wheelMass|vehicleMass|tuningWeight|effectiveMass|chassisMass|installedMass|dryInstalledMass|driverMass|payloadMass|mass|massscale","A heavier car needs more force to pick up speed. Heavier wheels also take more effort to spin, so they can slow acceleration more than the same weight elsewhere.","A lighter car picks up speed more easily. Where that weight sits still affects which tires have enough grip to put the power down.","Extra weight can slow acceleration and put more load on tires. Any added grip may not make up for the slower acceleration.","Removing mass can change axle loading and grip; compare balance as well as total weight.");
            Add("wheelInertia","The wheels take more effort to spin up or slow down, leaving less engine effort to move the car forward.","The wheels spin up and slow down more easily. This describes how hard they are to spin, rather than how much the whole car weighs.","Extra rotating load can slow acceleration and make the engine bog under a difficult launch.","Lighter rotating load changes how quickly wheel speed responds; available grip still limits acceleration.");
            Add("tireGrip|grip|frontLeftGrip|frontRightGrip|rearLeftGrip|rearRightGrip","More friction lets the contact patch carry more driving or braking force before sliding. Surface factors describe the road, not a tire upgrade.","Less friction makes it easier for the tire to slide under the same force.","Better grip can pass more load to the drivetrain. A grippier compound is not automatically longer-lived.","More of the engine's force may be lost to wheelspin, and braking grip can fall.");
            Add("tireHealth|componentCondition|tuningCondition|health|oilCondition|oilConditionClutch","A higher condition percentage means less wear or aging. Health is separate from a stored fault, leak or deposit problem.","Lower condition means more wear or aging and can reduce the affected component's performance before it fails.",null,"Performance or protection can be reduced and failures become more likely. Inspect individual parts and faults, not just the lowest percentage.");
            Add("rollingLife|rollinglife|slidingLife|slidinglife|life|servicelife","A larger life budget tolerates more equal use before wearing out. Reference mileage and sliding-work budgets are not a promise of remaining distance.","A smaller budget wears out sooner under the same loads, heat and driving behavior.",null,"Replacement may be needed sooner. More grip and more lifespan are separate properties.");
            Add("fuelMass|fuelLitres","More fuel gives more running time but also adds weight, even when fuel-consumption assistance is enabled.","Less fuel lightens the car but leaves less range before refueling.","The additional fuel adds mass and can slow acceleration.","The car can run out of fuel sooner.");
            Add("frontLoad|rearLoad","More resting force on this axle can increase its available tire force, but tire grip does not rise perfectly in proportion to load.","Less load gives that axle less force to work with. Live acceleration also transfers weight between axles.","If the added load comes from extra weight, the car is also harder to accelerate; compare total mass.","A driven axle with less load may spin more easily.");
            Add("cgPosition|payloadPosition","A larger distance from the front axle places the balance or payload farther toward the rear.","A smaller distance places it farther forward. Payload placement only matters when payload is present.","Rearward weight can reduce the grip available to front-driven tires.","Forward weight can reduce the load available to rear-driven tires.");
            Add("cgHeight|payloadHeight","A higher weight position causes more weight to transfer rearward during acceleration.","A lower position reduces that transfer. Payload height only matters when payload is present.","Front tires can lose more load during launch, which can hurt front-wheel drive grip.","Rear-wheel drive may get less extra rear load during launch.");
            Add("wheelbase","A longer distance between axles reduces weight transfer for the same mass, height and acceleration.","A shorter distance increases that transfer. Wheelbase is chassis geometry, not a standalone speed upgrade.","Rear-driven tires may gain less extra launch load.","Front-driven tires may lose more launch load.");
            Add("dragArea","The car has to push harder through the air, especially at high speed. This rating includes both its shape and how much area faces the air.","A lower drag area reduces that air resistance.","More power is spent pushing through air, reducing high-speed acceleration.",null);
            Add("rollingResistance","More rolling resistance uses more force simply to roll the tires, separate from air drag or wheelspin.","Less rolling resistance leaves more force available to accelerate the car.","Acceleration and fuel efficiency can worsen.",null);
            Add("drivetrainEfficiency","A larger share of engine power survives normal drivetrain losses. Additional live clutch or converter slip still loses power.","More engine power is lost before reaching the wheels.",null,"Less power reaches the tires despite unchanged engine dyno figures.");
            Add("flywheelMass|flywheelInertia|engineInertia|inertia","More rotating resistance stores more energy at the same revs. RPM changes more slowly, including falling more slowly in neutral.","Less rotating resistance lets the engine gain and lose revs faster, including between shifts.","The engine takes more work to rev up and can synchronize more slowly during a shift.","There is less stored energy to help engagement; a difficult launch can bog more easily and revs fall faster while disconnected.");
            Add("coolingTransfer|transfer|radiatorRejection|radiator|oilcooling","More heat can move out of the engine or oil and through the cooling system. Radiator ratings are heat removed per degree above outside temperature, before live airflow.","Less heat is removed, so heavy use raises temperatures faster. Fluid quantity and condition still matter.",null,"Sustained load is more likely to overheat the engine or oil.");
            Add("tankCapacity|oilCapacity|coolantCapacity|fluidcapacity|clutch-oil","The system has room for more liquid. A larger quantity can give more running range or thermal reserve, depending on the liquid.","There is room for less liquid, so there is less available range or thermal reserve.","Filling the extra space adds weight. Buying larger hardware does not automatically refill it.","A smaller capacity leaves less margin before fuel runs out or fluids become too low.");
            Add("fuelDensity","Each liter of fuel weighs more; this is a fuel property used in mass and consumption calculations.","Each liter weighs less. Density alone does not say which fuel makes more power.","The same tank volume adds more weight.","The same fuel mass represents more liters; compare consumption separately.");
            Add("idleFuelRate|fuelEfficiency","More fuel is used for the same idle time or energy output. Specific consumption means fuel used per unit of engine work, so a higher number is worse efficiency.","Less fuel is used for the same idle time or engine work. Live use also changes with load, wear and difficulty settings.","Fuel runs out sooner and refueling costs more for equal use.",null);
            Add("oilLitres|oil","More oil, up to the system's capacity, gives lubrication and cooling more reserve. Wet-clutch oil is a separate bath from engine oil.","Less oil leaves less reserve; going below the required level reduces protection or clutch cooling.","Extra oil adds weight. Topping up does not repair leaks or renew all old oil.","Low oil can reduce pressure or clutch capacity and cause heat, wear or damage.");
            Add("oilMinimum|fluidminimum","The oil pickup needs more liquid to remain reliable under the modeled loads.","The pickup can remain reliable with less liquid, although condition and acceleration still matter.","A higher minimum gives less margin before the current fill becomes unsafe.","A lower minimum is not a reason to ignore oil condition, leaks or acceleration-induced loss of supply.");
            Add("oilTemperature|temperature","Higher stored temperature means the fluid, part or tire was hotter when captured. Each has a useful temperature range.","Lower stored temperature means it was cooler. Cold tires and cold oil are not automatically at their best.","Too much heat can reduce grip, protection or component life; compare the part's temperature limits.","Too cold can reduce tire grip or oil performance. Race-start thermal assistance is applied separately.");
            Add("oilPressure","Higher retained oil pressure means a stronger recorded oil supply pressure, not a live reading while the engine is stopped.","Lower retained pressure can mean the recorded supply was weak; engine speed, oil quantity and faults matter.","A higher stored reading alone does not guarantee healthy lubrication on the next run.","Insufficient running pressure can damage the engine; inspect oil supply and pump condition.");
            Add("coolantLitres","More coolant, within capacity, gives the circuit more heat-carrying reserve.","Less coolant leaves less reserve before cooling becomes ineffective.","Extra coolant adds weight. Top-up does not reseal a leak or repair a radiator.","A low level can make temperatures rise and cause overheating.");
            Add("coolingCap|cappressure","A higher cap pressure lets the coolant resist boiling to a higher temperature.","A lower cap pressure allows earlier boiling and venting.","More pressure can increase leakage through damaged cooling hardware.","Earlier boiling can vent coolant and leave less liquid for the next run.");
            Add("oilBurned|oilLost|coolantLost","A larger total means more liquid has already been consumed, leaked or vented. This is past loss, not a current leak rate.","A smaller total means less recorded loss, not proof that every seal or component is healthy.","The recorded loss calls for checking present levels and its cause; topping up alone may not fix it.","Lower recorded loss does not rule out an existing fault.");
            Add("componentCount","More component packs are fitted. Individual pistons, valves and tire corners have their own condition within those packs.","Fewer packs are fitted. Some optional parts can be removed, while required missing hardware can block operation.","More fitted parts can add mass and maintenance; the count itself adds no power.","Check required hardware: missing parts may stop combustion, drive or braking.");
            Add("deposits","More dirt or residue can restrict the affected filter, airflow or fuel delivery.","Less buildup lets the component work closer to its clean condition.","Performance or protection may fall; clean or replace the affected component where supported.",null);
            Add("leak","A larger leak fault can lose more liquid or weaken the affected air/fuel system.","A smaller fault loses less through that component. Remaining leaks can still matter.","Top-ups may be used up sooner and cooling, lubrication or engine output can suffer.",null);
            Add("adjustment","A larger adjustment error means the mechanism is farther from its intended clearance or timing.","A smaller error means it is closer to its intended setting. This is a service fault, not the saved tune.","Poor adjustment can reduce running quality or damage matching parts; use the appropriate service action.",null);
            Add("work|distance","More accumulated sliding work or traveled distance records greater past use of this owned component.","Less accumulated use means less recorded history; current condition and faults still decide how well it works.","More use can mean less life left; check current health rather than treating the counter as remaining lifespan.","A low usage counter does not guarantee a healthy component.");
            Add("severity","A larger individual fault has a stronger effect on its cylinder, valve or other element.","A smaller fault has a weaker effect, but may still need service.","Running quality or protection can worsen even while other cylinders still work.",null);
            Add("heat","A higher heat-tolerance rating lets this part withstand hotter operation before modeled thermal damage accumulates.","A lower tolerance leaves less headroom for heavy use.","Tolerance is not cooling ability; the part can still overheat or fail under other loads.","The same sustained use may reach the damage range sooner.");
            Add("plates","More friction plates provide a different complete clutch assembly. Count alone does not specify its transferable torque.","Fewer plates describe a different assembly, not individual plate health.","Changing plate count requires matching whole hardware; compare actual capacity and mass.","Check complete-assembly capacity; fewer plates cannot be assumed sufficient for the same load.");
            Add("thermalmass","More heat energy is needed to raise the coolant temperature by one degree, slowing temperature changes.","The coolant temperature changes more quickly for the same added or removed heat.","The stored heat can also take longer to cool away; thermal reserve does not replace heat rejection.","Temperature can rise faster under heavy load.");
            Add("crownvolume","A more positive piston volume means a deeper dish, which lowers compression. Negative values describe a raised dome.","A lower or more negative value means less dish or more dome, which raises compression.","Reduced compression can weaken response; check effective compression on the whole engine.","Increased compression can raise petrol knock risk under boost; check valve clearance too.");
            Add("powerlimit","The fuel or ignition system can support a higher power demand before becoming a bottleneck.","It supports less demand before limiting engine output.","Unused capacity creates no horsepower by itself.","The system may cap power if the engine asks for more than it supports.");
            Add("injectorcylinders","The controller can support a larger compatible engine's cylinder count. This is calibration support, not physical injector count.","The controller supports fewer cylinders.","Extra supported cylinders add no power to the current engine and do not unlock unrelated controls.","A controller may no longer support the engine's actual cylinder count.");
            Add("idlecontrol","Stronger injection idle control helps hold idle steady while retaining the cam's natural roughness.","Weaker control allows more idle variation.","This does not repair worn or faulty engine hardware.","Idle may be less steady, especially with a rough cam or cold start.");
            Add("mixturevariation","More fuel-metering variation makes throttle transitions less consistent.","Less variation makes mixture transitions smoother; it is not a direct power multiplier.","The engine can stumble more during throttle changes.",null);
            Add("airflow","Better head or intake breathing can increase the engine's pulling force across the modeled power curve, within fuel and ignition limits.","More restricted breathing can reduce engine output.","Extra output can raise heat, fuel use and clutch or tire load.","Restricted airflow can limit power even with stronger internals.");
            Add("tireoptimal","This compound reaches its best grip at a higher tire temperature.","Its preferred temperature is lower, so less warming may be needed.","More warm-up may be needed before launch; colder-than-ideal tires can have less grip.","The tire can move above its ideal temperature sooner during a hot burnout or sustained slip.");
            Add("valvetrainrpm","Springs or other valve-control hardware can control motion at higher revs. For a cam, this is the control rating it requires from its springs.","Control hardware has a lower safe-speed rating, or the cam asks less of its springs.","A cam with a higher requirement needs matching springs; a stronger spring rating alone creates no power.","Lower-rated control hardware can lose valve control if engine speed exceeds its rating.");
            Add("camcontrolrequirement","This cam needs springs capable of controlling valve movement at a higher speed.","This cam needs less high-speed control from its springs. This is a requirement, not the engine's redline.","The fitted springs may no longer be strong enough for the cam's requirement; check their control rating.",null);
            Add("filtercapacity","The filter can handle more contamination before buildup harms its effectiveness.","It has less room to handle contamination under the same use.","The rating does not clean existing deposits or renew old oil.","Service may be needed sooner to retain protection.");
            Add("baffling","Better oil-pan barriers help keep oil around the pickup during acceleration.","Oil moves away from the pickup more easily under acceleration.","Baffling cannot replace missing oil or fix a failed pump.","Low oil plus hard acceleration can interrupt lubrication and damage the engine.");
            Add("pumpflow","The pump can circulate more fluid when supply, condition and restrictions permit.","Less fluid can circulate under the same demand.","Extra capability cannot make up for an empty reservoir or a blocked system.","Cooling or oil supply can become insufficient under heavy demand.");
            Add("quarterTime","A longer quarter-mile time means the copied test run took longer to finish.","A shorter time means a quicker copied run under the same test rules. Driver choices in a real race can differ.","The compared build finishes more slowly in this test.",null);
            Add("trapSpeed","A higher final probe speed means the copied test ended at a greater speed. Only a completed pass reaches the finish distance.","A lower final speed can indicate less acceleration, but an incomplete run ends at a different distance.","Higher finishing speed alone does not guarantee a quicker pass; check completion and elapsed time.","A completed pass at lower speed generally has less finishing pace; check whether the probe actually completed.");
            Add("maxWheelSlip","More measured tire slip means wheel rotation differs more from road travel in the copied driving test.","Less measured slip means the tires stayed closer to road speed. Some slip is normal when using available grip.","Excess spin wastes acceleration and heats or wears tires.","Less slip alone does not guarantee speed; a weak engine can also produce little spin.");
            Add("maxClutchSlip","A larger measured RPM gap means the engine and gearbox were turning at more different speeds during the copied test.","A smaller gap means the clutch kept their speeds closer together.","Excess sustained slip loses wheel power and builds clutch heat and wear; brief shift slip can be normal.","Closer coupling can pass more load to tires or weaker drivetrain parts; it is not extra engine power.");
            Add("warningCount","More inspection warnings mean more issues or limits deserve attention. Their severity matters more than count alone.","Fewer warnings mean fewer reported concerns, not a guarantee that abuse cannot break the car.","Review the warnings for causes and suggested fixes; do not treat them as an automatic race result.","Remaining critical warnings still matter, even with a lower total.");
            Add("attenuation","More sound attenuation makes this exhaust section quieter before its active amount is applied.","Less attenuation leaves a louder exhaust sound. This setting changes sound, not engine power.","The exhaust may be harder to hear.","The exhaust may be louder than desired; no power gain is implied.");
            Add("amount","This exhaust element contributes more strongly to the sound filtering for its type.","It contributes less strongly, moving the sound closer to the unfiltered path.","Stronger filtering can soften or reduce the sound, depending on the section.","Reduced filtering can sound louder or harsher; it does not create horsepower.");
            Add("cutoff","A higher cutoff lets more high-frequency sound through the exhaust section, making it brighter.","A lower cutoff removes more high-frequency detail, making it duller or deeper.","Extra high-frequency content can sound harsh.","Too much filtering can make the engine sound muffled.");
            Add("pulse","More pulse smoothing blends individual combustion beats together.","Less smoothing leaves the individual beats more raw and distinct.","Too much smoothing can hide the engine's character.","Sharper pulses can sound harsher.");
            Add("resonance","The exhaust emphasis or dip is centered on a higher sound frequency.","It is centered on a lower frequency. This shifts tone rather than overall power or loudness.","The emphasis may become more piercing, depending on gain and width.","Low-frequency emphasis can make the sound boomy, depending on gain and width.");
            Add("gain","A higher value boosts this sound band more, or cuts it less if the value is negative.","A lower value reduces this band more, or boosts it less.","A boosted band can become too prominent or harsh.","A stronger cut can remove useful engine character.");
            Add("q","A higher Q focuses the sound boost or cut on a narrower band of frequencies.","A lower Q spreads it over a wider band.","A narrow boost can produce an overly ringing tone.","A broad cut or boost can change more of the engine's sound than intended.");
            Add("shiftLanding","The engine lands at higher revs when the next gear engages, using the calculated shift point and ratios.","The engine lands at lower revs after that shift.","Closely spaced gears can keep the engine high in its range but require more shifts over a given speed gain.","A large RPM drop can put the engine below its useful pull or boost range.");
        }
        internal static Directions Find(string id)
        {
            if(id==null)return null;
            if(id=="part:Clutch:oilCondition")id="oilConditionClutch";
            else if(id=="part:Camshaft:rating:valvetrainrpm")id="camcontrolrequirement";
            else if(id.StartsWith("part:",StringComparison.Ordinal)||id.StartsWith("exhaust:",StringComparison.Ordinal))id=id.Substring(id.LastIndexOf(':')+1);
            else if(id.IndexOf(':')>=0)id=id.Substring(0,id.IndexOf(':'));
            return entries.TryGetValue(id,out var value)?value:null;
        }
        internal static string Explain(NativeStatDefinition definition,NativeStatsSnapshot current,NativeStatsSnapshot proposed)
        {
            var directions=Find(definition.Id);
            if(directions==null)return definition.Explanation(current); // Unrecognized extension retains its authored help.
            string text="More: "+directions.More+"\n\nLess: "+directions.Less;
            if(proposed==null)return text;
            var a=definition.Number(current);var b=definition.Number(proposed);string drawback;
            if(!a.HasValue||!b.HasValue)drawback="This value is unavailable on one or both builds, so a higher/lower effect cannot be established. Check fitted hardware and completed test results.";
            else if(Math.Abs(b.Value-a.Value)<.00001)drawback="This stat is unchanged. It adds no new drawback to this comparison; other changed stats can still matter.";
            else {
                bool higher=b.Value>a.Value;
                string risk=higher?directions.HigherDrawback:directions.LowerDrawback;
                drawback="The compared value is "+(higher?"higher. ":"lower. ")+(risk??"There is no direct drawback from this change alone. Check other changed stats and build warnings.");
            }
            return text+"\n\nDrawbacks in this comparison: "+drawback;
        }
    }
}
